clc;
clear all;
close all;
syms n;
x= sin(n);
f=ztrans(x); 
% transform 
pretty(f ); %[output:8e0e26ce]
disp('Zsin(n):'); %[output:07603d4d]
iztrans(f);
disp('Zsin(n):'); %[output:8814be3d]
pretty(iztrans(f)); %[output:23e8a5c1]
figure; %[output:5d890994]
pz = tf([1],[1,2,1]);
pzmap(pz); %[output:5d890994]
grid on; %[output:5d890994]
title('Pole-Zero Plot'); %[output:5d890994]

